-- NASAQ v3: import in phpMyAdmin after v2. Preserve existing records.
CREATE TABLE IF NOT EXISTS customers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS customer_orders(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id INT UNSIGNED NOT NULL,item_id INT UNSIGNED NOT NULL,reference VARCHAR(32) NOT NULL UNIQUE,amount DECIMAL(10,2) NULL,status ENUM('new','reviewing','approved','completed','cancelled') NOT NULL DEFAULT 'new',note TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(customer_id),INDEX(item_id),CONSTRAINT fk_nasaq_order_customer FOREIGN KEY(customer_id) REFERENCES customers(id),CONSTRAINT fk_nasaq_order_item FOREIGN KEY(item_id) REFERENCES items(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS item_images(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,item_id INT UNSIGNED NOT NULL,image_url VARCHAR(2048) NOT NULL,sort_order INT NOT NULL DEFAULT 0,INDEX(item_id),CONSTRAINT fk_nasaq_image_item FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS activity_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_type ENUM('admin','customer','system') NOT NULL,actor_id INT UNSIGNED NULL,action VARCHAR(90) NOT NULL,subject_type VARCHAR(50) NULL,subject_id INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_roles(admin_id INT UNSIGNED NOT NULL PRIMARY KEY,role ENUM('owner','editor','sales','support') NOT NULL DEFAULT 'owner',CONSTRAINT fk_nasaq_adminrole FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO admin_roles(admin_id,role) SELECT id,'owner' FROM admins;
